const items = $input.all();                                                                                                                                       
const LIMIT = 500;                                                                                                                                                  

// Persist send count across workflow runs using n8n static data                                                                                                    
const staticData = $getWorkflowStaticData('global');                                                                                                              
const today = new Date().toISOString().slice(0, 10); // YYYY-MM-DD                                                                                                  

if (staticData.date !== today) {                                                                                                                                    
  staticData.date = today;
  staticData.sentToday = 0;                                                                                                                                         
}                                                                                                                                                                 

const sentToday = staticData.sentToday || 0;
const remaining = LIMIT - sentToday;

if (remaining <= 0) {
  throw new Error(`Daily Gmail limit reached. Sent today: ${sentToday}/${LIMIT}. Try again tomorrow.`);                                                             
}                                                                                                                                                                 

const allowedItems = items.slice(0, remaining);
staticData.sentToday = sentToday + allowedItems.length;                                                                                                             

return allowedItems;

const lead = $('Split in Batches').item.json;                                                                                                                     
const gmailResult = $input.item.json;                                                                                                                               

let emailSent, deliveryStatus;

if (gmailResult.id && !gmailResult.error) {                                                                                                                         
  emailSent = 'Yes';
  deliveryStatus = 'Delivered';                                                                                                                                     
} else if (gmailResult.error) {                                                                                                                                   
  const errorMsg = (gmailResult.error.message || '').toLowerCase();
  const isDeliveryFailure = /\b5[0-9]{2}\b/.test(errorMsg) ||                                                                                                       
    /recipient|does not exist|no such user|user unknown|mailbox not found|delivery fail/i.test(errorMsg);

  if (isDeliveryFailure) {                                                                                                                                        
    emailSent = 'Yes';                                                                                                                                              
    deliveryStatus = 'Bounced';                                                                                                                                   
  } else {                                                                                                                                                          
    emailSent = 'No';
    deliveryStatus = 'Undelivered';                                                                                                                                 
  }                                                                                                                                                               
} else {
  emailSent = 'No';
  deliveryStatus = 'Unknown';
}                                                                                                                                                                   

return {                                                                                                                                                            
  json: {                                                                                                                                                         
    batchId: lead.batchId,
    businessType: lead.businessType,
    businessName: lead.businessName,
    location: lead.location,
    email: lead.email,
    validationStatus: lead.validationStatus,                                                                                                                        
    emailSent,
    deliveryStatus,                                                                                                                                                 
    dateSent: new Date().toISOString(),                                                                                                                           
    subject: lead.subject,
    generatedBody: lead.generatedBody
  }                                                                                                                                                                 
};

const lead = $('Workflow Input').item.json;
const response = $input.item.json;                                                                                                                                  

let text = response.content[0].text.trim();                                                                                                                         

// Strip markdown code blocks if Claude wraps the response                                                                                                          
text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();

const generated = JSON.parse(text);                                                                                                                               

return {                                                                                                                                                          
  json: {
    ...lead,                                                                                                                                                        
    subject: generated.subject,
    generatedBody: generated.body                                                                                                                                   
  }                                                                                                                                                               
};

const item = $input.item.json;

return {                                                                                                                                                          
  json: {
    ...item,                                                                                                                                                        
    apiBody: JSON.stringify({
      model: "claude-haiku-4-5-20251001",                                                                                                                           
      max_tokens: 300,                                                                                                                                            
      system: "You write short, human cold outreach emails for small businesses. Always return valid JSON with exactly two keys: subject and body. No extra text outside the JSON.",                                                                                                                                                 
      messages: [
        {                                                                                                                                                           
          role: "user",                                                                                                                                           
          content: `Write a cold email to ${item.businessName}, a ${item.businessType} in ${item.location}. Sign off with the name "Adnan". Rules: Subject under 8 words. Body
   under 100 words. First line must reference this specific business, never generic. One CTA only, a short question or calendar link. Tone: direct, human, no         
  buzzwords, no mention of AI. Return raw JSON only, no markdown, no code blocks: { "subject": "...", "body": "..." }`
        }                                                                                                                                                           
      ]                                                                                                                                                           
    })
  }
};
